from test_bufftap import test

test('Queue clicks retain helper tracking and silent sequence intent', "local B=BuffTap; B.db.buffQueue=true; refresh(); local q=B.queueButtons[1]; assert(q and q.action); local action=q.action; local original=B.BeginHelperAttempt; local called; B.BeginHelperAttempt=function(self,a) called=a; original(self,a) end; q.scripts.PreClick(q,'LeftButton',false); assert(called==action); assert(B.buffQueueQuietUntil>now); assert(B.selfBuffAttempts[action.id])")

test('Queue click starts SmartShift for the queued self buff', "local B=BuffTap; B.db.buffQueue=true; B.db.smartShift=true; spell(768,'Cat Form',1); GetShapeshiftForm=function() return 1 end; GetShapeshiftFormInfo=function() return 132115,true,true,768 end; refresh(); local q=B.queueButtons[1]; assert(q and q.action.target=='player'); q.scripts.PreClick(q,'LeftButton',false); assert(B.smartShiftIntent and B.smartShiftIntent.buffID==q.action.id)")

test('Combat estimates use expiring buff mute rather than main action', "local B=BuffTap; B.db.combatExpiry=true; B.db.sound=true; B.db.pauseResting=false; B:SetBuffAlertEnabled('personal','motw',false); local played=0; PlaySoundFile=function() played=played+1; return true end; PlaySound=function() played=played+1; return true end; combat=true; B:FireCombatExpiry({key='motw',name='Mark',icon=1,expiresAt=now+5}); assert(played==0,'muted played '..played); B:SetBuffAlertEnabled('personal','thorns',true); B.lastAlertSound=nil; B:FireCombatExpiry({key='thorns',name='Thorns',icon=1,expiresAt=now+5}); assert(played==1,'audible played '..played..' reason '..tostring((B:ReminderPauseReason())))")

test('Combat estimates honor explicit buff sound override', "local B=BuffTap; B.db.combatExpiry=true; B.db.sound=true; B.db.pauseResting=false; B:SetBuffAlertSound('personal','motw','holylight'); local played; PlaySoundFile=function(path) played=path; return true end; combat=true; B:FireCombatExpiry({key='motw',name='Mark',icon=1,expiresAt=now+5}); assert(played and played:find('HolyLight',1,true),tostring(played))")

test('Combat estimate visual and audio pause then visual resumes quietly', "local B=BuffTap; B.db.combatExpiry=true; B.db.sound=true; local played=0; B.PlayAlert=function() played=played+1 end; B.pauseUntil=now+10; combat=true; B:FireCombatExpiry({key='motw',name='Mark',icon=1,expiresAt=now+20}); assert(not B.combatExpiryFrame:IsShown()); B.pauseUntil=nil; B:UpdateCombatExpiryFrame(); assert(B.combatExpiryFrame:IsShown()); local before=played; B:UpdateCombatExpiryFrame(); assert(played==before)")

test('Bounded queue counts explicitly show a lower bound', "local B=BuffTap; B.db.buffQueue=true; local old=B.EngineSelect; local n=0; B.EngineSelect=function(self) n=n+1; return {key='thorns',id=467,secureType='spell',target='party1',targetGUID='P'..n} end; local queue=B:CollectBuffQueue(nil); B.EngineSelect=old; assert(#queue==1 and queue[1].count==12 and queue[1].atLeast==true); assert(B.queuePass==nil)")


test('Passive estimate does not inherit an unrelated cleanse sound category', "local B=BuffTap; B.db.combatExpiry=true; B.db.sound=true; B.db.cleanseSoundEnabled=false; B.db.pauseResting=false; B.action={source='cleanse',key='poison',target='player'}; local played=0; PlaySoundFile=function() played=played+1; return true end; PlaySound=function() played=played+1; return true end; combat=true; B:FireCombatExpiry({key='motw',name='Mark',icon=1,expiresAt=now+5}); assert(played==1)")
